from pathlib import Path

R5 = Path('/private/tmp/fgmetal-step11d2-r5-diagnostic-source-c-20261006')
BRIDGE = Path('/private/tmp/fgmetal-step11d2-bridge-diagnostic-c-20261006/source')


def edit(path, replacements):
    text = path.read_text()
    for old, new in replacements:
        count = text.count(old)
        if count != 1:
            raise RuntimeError(f'{path}: expected one match, got {count}: {old[:110]!r}')
        text = text.replace(old, new, 1)
    path.write_text(text)

# Additional wire fields keep the diagnostic run and stage identity explicit.
for path in (BRIDGE / 'bridge_protocol.h', R5 / 'src/dxvk/dxvk_metal_bridge_protocol.h'):
    text = path.read_text()
    text = text.replace('  uint64_t trace_app_frame_id;\n',
        '  uint64_t trace_app_frame_id;\n  uint64_t trace_generation;\n  uint64_t trace_command_buffer_create_begin_ns;\n  uint64_t trace_encoder_create_begin_ns;\n', 1)
    text = text.replace('sizeof(fgmb_packet) == 520', 'sizeof(fgmb_packet) == 544')
    path.write_text(text)

# PE bridge was copied from the matching status-v3 R5 bridge. New trace fields are diagnostic-only.
# Unixlib call timing fields already share mach_continuous_time with Wine QPC.

